	l := lexer.New(input)
	p := parser.New(l)
	program := p.ParseProgram()

	c := checker.New()
	c.Check(program)

	compiler := New(c.(*checker.Checker).GlobalScope().(*checker.SymbolTable))
	compiler.Compile(program)

